#include <iostream>
#include <string_view>

struct KeyAction {
    std::string_view key;
    std::string_view role;
};

int main() {
    constexpr KeyAction shortcuts[] = {
        {"F2", "Save file"},
        {"F3", "Open file"},
        {"F7", "Trace into functions"},
        {"F8", "Step over functions"},
        {"F9", "Compile and link"},
        {"Ctrl-F9", "Run executable"},
        {"Alt-F5", "View output screen"}
    };

    for (const auto& item : shortcuts) {
        std::cout << item.key << ": " << item.role << "\n";
    }
    return 0;
}

