#include <iostream>
#include <cmath>

int main() {
    // Input: he so kieu so thuc (double)
    double a = 1.0;
    double b = -3.0;
    double c = 2.0;

    // Thuat toan: tinh delta
    double delta = b * b - 4.0 * a * c;

    if (delta > 0.0) {
        // Output: nghiem x1, x2 la cac so thuc
        double x1 = (-b + std::sqrt(delta)) / (2.0 * a);
        double x2 = (-b - std::sqrt(delta)) / (2.0 * a);
        std::cout << "x1 = " << x1 << ", x2 = " << x2 << "\n";
    } else if (delta == 0.0) {
        double x = -b / (2.0 * a);
        std::cout << "x = " << x << "\n";
    } else {
        std::cout << "Vo nghiem\n";
    }

    return 0;
}
